<section class="hero"><div><p class="eyebrow"><?= $e($t('TRUTH · AUTHORSHIP · OWNERSHIP')) ?></p><h1><?= $e($t('A story travels.')) ?><br><em><?= $e($t('Its people stay with it.')) ?></em></h1><p class="lead"><?= $e($t('subtitle')) ?> <?= $e($t('A passport records who claims a story, what its stewards allow, and how a MOCK fee is shared.')) ?></p><div class="actions"><a class="button" href="/dashboard/new"><?= $e($t('register')) ?> <span aria-hidden="true">↗</span></a><a href="#passports"><?= $e($t('Explore the demo')) ?> ↓</a></div></div><aside class="hero-card"><span class="eyebrow"><?= $e($t('EVERY STORY HAS PEOPLE')) ?></span><span class="hero-symbol" aria-hidden="true">◎</span><h2><?= $e($t('Credit. Consent. Community.')) ?></h2><p><?= $e($t('A declared record of care, with a transparent MOCK ledger.')) ?></p><span class="badge"><?= $e($t('Claims recorded · limits visible')) ?></span></aside></section>
<section id="passports"><div class="section-heading"><div><p class="eyebrow"><?= $e($t('THE REGISTRY')) ?></p><h2><?= $e($t('Stories, with their terms attached.')) ?></h2></div><span><?= count($stories) ?> <?= $e($t('registered claims')) ?></span></div><div class="cards"><?php foreach ($stories as $story): ?><article class="card story-card"><div class="card-top"><span class="badge"><?= $e($story['sensitivity'] === 'RESTRICTED' ? $t('Restricted') : strtoupper($story['mediaType'])) ?></span><span class="mono"><?= $e($story['id']) ?></span></div><div class="story-art" aria-hidden="true"><?= $story['sensitivity'] === 'RESTRICTED' ? '◈' : '↗' ?></div><p class="eyebrow"><?= $e($story['creator']['name']) ?></p><h3><?= $e($story['title'] ?? $t('restricted')) ?></h3><p><?= $e($story['sensitivity'] === 'RESTRICTED' ? $t('Held privately by its steward.') : mb_strimwidth($story['contextNote'], 0, 160, '…')) ?></p><div class="card-bottom"><span class="status"><?= $e(\Passport\Copy::STATUS[$story['status']]) ?></span><a href="/p/<?= $e($story['id']) ?>"><?= $e($t('passport')) ?> ↗</a></div></article><?php endforeach ?></div><?php if (!$stories): ?><p class="empty"><?= $e($t('empty')) ?> <a href="/dashboard/new"><?= $e($t('register')) ?></a></p><?php endif ?></section>
